import React from "react";

const CertDB_Products = ({ onProductClick }) => {
    const products = [
        { id: 1, name: "Product A", description: "Details about A" },
        { id: 2, name: "Product B", description: "Details about B" },
        // Add more products
    ];

    return (
        <table>
            <thead>
                <tr><th>Product</th></tr>
            </thead>
            <tbody>
                {products.map((product) => (
                    <tr key={product.id}>
                        <td>
                            <a href="#!" onClick={() => onProductClick(product)}>
                                {product.name}
                            </a>
                        </td>
                    </tr>
                ))}
            </tbody>
        </table>
    );
};

export default CertDB_Products;
